fun modInv(a: Long, p: Long): Long {
    var a = a
    var res = 1L
    var b = p - 2
    while (b > 0) {
        if (b % 2 == 1L) {
            res = res * a % p
        }
        a = a * a % p
        b /= 2
    }
    return res
}

fun comb(n: Long, k: Long, p: Long, fact: LongArray, inv_fact: LongArray): Long {
    if (n < 0 || k < 0 || n < k) return 0
    return fact[n.toInt()] * inv_fact[k.toInt()] % p * inv_fact[(n - k).toInt()] % p
}
